package com.hospital.system.service; import com.hospital.system.model.Department; import com.hospital.system.repository.DepartmentRepository; import com.hospital.system.exception.ApiException; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.*; @Service public class DepartmentService {private final DepartmentRepository r; public DepartmentService(DepartmentRepository r){this.r=r;} public List<Department> all(){return r.all();} public Department one(Long id){return r.one(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Department not found"));} public Department add(Department d){r.add(d);return r.all().stream().filter(x->x.departmentName.equals(d.departmentName)).findFirst().orElseThrow();} public Department update(Long id,Department d){one(id);r.update(id,d);return one(id);} public void delete(Long id){one(id);r.delete(id);} }
